#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>market={0.01,-0.02,0.03,0.02},asset={0.012,-0.03,0.025,0.018};
double meanMarket=0,meanAsset=0,cov=0,var=0;
for(int i=0;i<4;i++){meanMarket+=market[i]/4;meanAsset+=asset[i]/4;}
for(int i=0;i<4;i++){
cov+=(market[i]-meanMarket)*(asset[i]-meanAsset);
var+=pow(market[i]-meanMarket,2);
}
cout<<"beta "<<cov/var<<"\n";
return 0;
}
